CREATE TABLE whatsapp_order_confirmations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, order_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'queued', origin VARCHAR(16) NOT NULL DEFAULT 'landing', conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, message_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, quote_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, order_version INT NULL, error VARCHAR(500) NULL, reply VARCHAR(16) NULL, reply_message_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, reply_wamid VARCHAR(255) NULL, reply_pending TINYINT(1) NOT NULL DEFAULT 0, locked_at DATETIME(6) NULL, sent_at DATETIME(6) NULL, replied_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_order_confirmations_order_uq (order_id), UNIQUE KEY whatsapp_order_confirmations_owner_uq (id,user_id), KEY whatsapp_order_confirmations_due_idx (status,reply_pending), KEY whatsapp_order_confirmations_owner_idx (user_id,created_at), KEY whatsapp_order_confirmations_chat_idx (conversation_id,status), CONSTRAINT whatsapp_order_confirmations_status_ck CHECK (status IN ('queued','sending','sent','failed','skipped','confirmed','change','stale')), CONSTRAINT whatsapp_order_confirmations_origin_ck CHECK (origin IN ('landing','manual')), CONSTRAINT whatsapp_order_confirmations_reply_ck CHECK (reply IS NULL OR reply IN ('confirm','change')), CONSTRAINT whatsapp_order_confirmations_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_order_confirmations_order_fk FOREIGN KEY (order_id,user_id) REFERENCES orders(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci